(function(){
  var P = AutoJS.players()[0];
  var Cur = Java.loadClass('com.merlinkitsune.astral_dice.compat.curios.CuriosApi');
  var SC = Java.loadClass('com.merlinkitsune.astral_dice.compat.curios.SlotContext');
  var DCI = Java.loadClass('com.merlinkitsune.astral_dice.item.dice.DiceCurioItem');
  var ItemStack = Java.loadClass('net.minecraft.world.item.ItemStack');
  AutoJS.command('kill @e[type=!player,distance=..48]');
  AutoJS.command('clear @a');
  AutoJS.command('effect clear @a');
  var inv = Cur.getCuriosInventory(P).get();
  var diceH = inv.getStacksHandler('dice').get();
  var chipH = inv.getStacksHandler('chip').get();
  diceH.getStacks().setStackInSlot(0, ItemStack.EMPTY);
  DCI.refreshChipSlotCount(P);
  var probe = AutoJS.stack('astral_dice:diamond_dice', 1);
  var diceItem = probe.getItem();
  return {
    diceSlotEmpty: diceH.getStacks().getStackInSlot(0).isEmpty(),
    chipSlotsBase: chipH.getSlots(),
    canEquipDice: diceItem.canEquip(new SC(P, 'dice', 0), probe),
    canEquipStand: diceItem.canEquip(new SC(P, 'stand', 0), probe),
    cardSlotsDeclared: DCI.getCardSlots(probe)
  };
})()

(function(){
  var P = AutoJS.players()[0];
  var Cur = Java.loadClass('com.merlinkitsune.astral_dice.compat.curios.CuriosApi');
  var CSU = Java.loadClass('com.merlinkitsune.astral_dice.item.CurioSlotUtil');
  var DCI = Java.loadClass('com.merlinkitsune.astral_dice.item.dice.DiceCurioItem');
  var DC = Java.loadClass('com.merlinkitsune.astral_dice.component.ModDataComponents');
  var ItemStack = Java.loadClass('net.minecraft.world.item.ItemStack');
  var inv = Cur.getCuriosInventory(P).get();
  var diceH = inv.getStacksHandler('dice').get();
  var chipH = inv.getStacksHandler('chip').get();
  diceH.getStacks().setStackInSlot(0, ItemStack.EMPTY);
  DCI.refreshChipSlotCount(P);
  var chipBefore = chipH.getSlots();
  P.getInventory().selected = 0;
  P.getInventory().setItem(0, AutoJS.stack('astral_dice:diamond_dice', 1));
  var held = AutoJS.held(P);
  var heldId = AutoJS.id(held);
  var countBefore = held.getCount();
  var used = AutoJS.use();
  var countAfterUse = AutoJS.held(P).getCount();
  var equipOk = CSU.tryAutoEquip(P, AutoJS.held(P), 'dice').getResult().consumesAction();
  var inSlot = diceH.getStacks().getStackInSlot(0);
  DCI.refreshChipSlotCount(P);
  var out = {
    chipSlotsBefore: chipBefore,
    heldId: heldId,
    heldCountBefore: countBefore,
    useConsumed: used,
    heldCountAfterUse: countAfterUse,
    equipOk: equipOk,
    diceSlotId: inSlot.isEmpty() ? 'empty' : String(AutoJS.id(inSlot)),
    diceSlotCount: inSlot.getCount(),
    chipSlotsAfter: chipH.getSlots(),
    cardSlots: DCI.getCardSlots(inSlot),
    enhancementPresent: DC.WEAPON_ENHANCEMENT.has(inSlot)
  };
  return out;
})()

(function(){
  var P = AutoJS.players()[0];
  var Cur = Java.loadClass('com.merlinkitsune.astral_dice.compat.curios.CuriosApi');
  var DCI = Java.loadClass('com.merlinkitsune.astral_dice.item.dice.DiceCurioItem');
