  var inv = Cur.getCuriosInventory(P).get();
  inv.getStacksHandler('dice').get().getStacks().setStackInSlot(0, ItemStack.EMPTY);
  DCI.refreshChipSlotCount(P);
  AutoJS.command('clear @a');
  AutoJS.command('effect clear @a');
  return {
    diceSlotEmptyAfter: inv.getStacksHandler('dice').get().getStacks().getStackInSlot(0).isEmpty(),
    chipSlotsFinal: inv.getStacksHandler('chip').get().getSlots()
  };
})()
